/**
 * @name Sensitive data in logs
 * @description Logging sensitive information can lead to information disclosure
 * @kind path-problem
 * @problem.severity warning
 * @id py/s3fs-sensitive-log
 * @tags security
 *        external/cwe/cwe-532
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

class SensitiveDataSource extends DataFlow::Node {
  SensitiveDataSource() {
    exists(DataFlow::AttrRead attr |
      this = attr and
      attr.getAttributeName() in ["password", "secret", "token", "key", "credential", "aws_secret_access_key", "aws_session_token"]
    )
  }
}

module SensitiveLogConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof SensitiveDataSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("logging").getMember(["debug", "info", "warning", "error", "critical"]).getACall() and
      sink = call.getArg(_)
    )
  }
}

module SensitiveLogFlow = TaintTracking::Global<SensitiveLogConfig>;
import SensitiveLogFlow::PathGraph

from SensitiveLogFlow::PathNode source, SensitiveLogFlow::PathNode sink
where SensitiveLogFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Sensitive data logged from $@.", source.getNode(), "sensitive source"

